//! Cargo-driven `aclayers.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is aclayers-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-kernel.json", "_DllMain@12", Some(0x780e0000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMain", Some(0x7ff76000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMain", Some(0x7ff76000000u64)),
        o => panic!("aclayers-cargo: unsupported arch {o}"),
    };

    let static_libs: &[&str] = match arch.as_str() {
        "x86" => &["dll/appcompat/shims/shimlib/libshimlib.a"],
        "x86_64" => &["dll/appcompat/shims/shimlib/libshimlib.a"],
        "aarch64" => &["dll/appcompat/shims/shimlib/libshimlib.a"],
        _ => unreachable!(),
    };

    Linker::new(target_json)
        .rust_staticlib("aclayers-rust")
        .c_from_compile_db("aclayers_shims", &["dll/appcompat/shims/layer/rust_cohab_stub.c"])
        .spec2def("dll/appcompat/shims/layer/layer.spec", "aclayers.dll")
        .import_lib("win32ss/user/user32/user32.spec", "user32.dll", "user32")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // cmake-built static libraries, reused until each has a cargo home.
        .static_libs(static_libs)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
